      "te": "కొంతమంది తత్వవేత్తలు చర్యలు చెడుగా వదిలివేయబడాలని ప్రకటించారు; మరికొందరు త్యాగం, బహుమతి మరియు కాఠిన్యం వంటి చర్యలను విడిచిపెట్టరాదని ప్రకటించారు.",
      "hi": "श्रीभगवान् बोले -- कई विद्वान् काम्य-कर्मोंके त्यागको संन्यास कहते हैं और कई विद्वान् सम्पूर्ण कर्मोंके फलके त्यागको त्याग कहते हैं। कई विद्वान् कहते हैं कि कर्मोंको दोषकी तरह छोड़ देना चाहिये और कई विद्वान् कहते हैं कि यज्ञ, दान और तप-रूप कर्मोंका त्याग नहीं करना चाहिये।",
      "sa": "त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः।\n\nयज्ञदानतपःकर्म न त्याज्यमिति चापरे।।18.3।।",
      "gu": "વિદ્વાનોમાં એક મત મુજબ તમામ કર્મો દોષથી યુક્ત છે અને તેથી તેમને ત્યાગવા યોગ્ય ગણાય છે. બીજી તરફ, કેટલાક વિદ્વાનો માનવે છે કે યજ્ઞ, દાન અને તપ જેવા શુભ કર્મોનો ત્યાગ કરવો યોગ્ય નથી. આ શ્લોકમાં બંને મતલબોને સ્પષ્ટ રીતે રજૂ કરવામાં આવ્યા છે.",
