      "te": "శారీరక బాధలకు భయపడి (అది బాధాకరమైనది కాబట్టి) క్రియను విడిచిపెట్టినవాడు, అటువంటి రాజస త్యజించడం ద్వారా త్యజించిన పుణ్యాన్ని పొందలేడు.",
