      "hi": "जो कर्ता असावधान, अशिक्षित, ऐंठ-अकड़वाला, जिद्दी, उपकारीका अपकार करनेवाला, आलसी, विषादी और दीर्घसूत्री है, वह तामस कहा जाता है।",
      "sa": "अयुक्तः प्राकृतः स्तब्धः शठो नैष्कृतिकोऽलसः।विषादी दीर्घसूत्री च कर्ता तामस उच्यते।।18.28।।",
      "gu": "તો તે કર્તા અયોગ્ય, અભ્યાસ વિનાનો, અહંકારી, છલકપટી, બીજાના જીવનનું નુકસાન કરનારો, દુઃખી, આળસુ અને કામમાં વિલંબ કરનારો હોય છે; આવા ગુણો ધરાવનારને તામસિક કર્તા કહે છે.",
