      "gu": "એ ધૃતિ સાત્ત્વિક ગણાય છે જે મન, પ્રાણ અને ઇન્દ્રિયોને નિયંત્રિત કરે છે અને ધ્યાનયોગ દ્વારા મનને એકાગ્ર રાખે છે. આવી ધૃતિ અડગ અને અવ્યભિચારિ હોય છે, એટલે કે કોઈપણ પરિસ્થિતિમાં ડગમગતી નથી.",
