      "te": "మొదట విషంలా ఉంటుంది, కానీ చివరికి అమృతం వంటిది-ఆ ఆనందం సాత్వికమైనదిగా ప్రకటించబడుతుంది, స్వీయ-సాక్షాత్కారం కారణంగా ఒకరి స్వంత మనస్సు యొక్క స్వచ్ఛత నుండి పుట్టినది.",
      "hi": "हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! अब तीन प्रकारके सुखको भी तुम मेरेसे सुनो। जिसमें अभ्याससे रमण होता है और जिससे दुःखोंका अन्त हो जाता है, ऐसा वह परमात्मविषयक बुद्धिकी प्रसन्नतासे पैदा होनेवाला जो सुख (सांसारिक आसक्तिके कारण) आरम्भमें विषकी तरह और परिणाममें अमृतकी तरह होता है, वह सुख सात्त्विक कहा गया है।",
      "sa": "यत्तदग्रे विषमिव परिणामेऽमृतोपमम्।तत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम्।।18.37।।",
      "gu": "'વિષમિવ' એ અર્થ છે કે આ સુખ શરૂઆતમાં તકલીફદાયક અથવા દુઃખદાયી લાગે છે, જેમ કે કોઈને ઝેર જેવું. પરંતુ, આ દુખદ વલણ અંતે અમૃત જેવું મીઠું લાગે છે. આ શ્લોકમાં સુખની શરૂઆતમાં મુશ્કેલીઓ હોવા છતાં તેના અંતે આનંદની અનુભૂતિની વાત છે.",
