      "hi": "अपने-अपने कर्ममें तत्परतापूर्वक लगा हुआ मनुष्य सम्यक् सिद्धि-(परमात्मा-)को प्राप्त कर लेता है। अपने कर्ममें लगा हुआ मनुष्य जिस प्रकार सिद्धिको प्राप्त होता है? उस प्रकारको तू मेरेसे सुन।",
      "sa": "स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः।स्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु।।18.45।।",
      "gu": "મનુષ્ય પોતાના સ્વાભાવિક કર્મમાં લગનથી પ્રવૃત થાય છે ત્યારે તે પરમ સિદ્ધિ પ્રાપ્ત કરી શકે છે.",
