    "teluguMeaning": "ఓ అర్జునా, తను పుట్టిన కర్తవ్యాన్ని తప్పుదారి పట్టించకూడదు; ఎందుకంటే, అగ్ని పొగతో ఉన్నట్లే, అన్ని పనులు చెడుచే చుట్టబడి ఉంటాయి.",
    "iast": "saha-jaṁ karma kaunteya sa-doṣham api na tyajet\nsarvārambhā hi doṣheṇa dhūmenāgnir ivāvṛitāḥ",
    "translations": {
      "en": "One should not, O Arjuna, abandon the duty to which one is born, though it may be faulty; for, all undertakings are enveloped by evil, just as fire is by smoke.",
      "te": "ఓ అర్జునా, తను పుట్టిన కర్తవ్యాన్ని తప్పుదారి పట్టించకూడదు; ఎందుకంటే, అగ్ని పొగతో ఉన్నట్లే, అన్ని పనులు చెడుచే చుట్టబడి ఉంటాయి.",
      "hi": "हे कुन्तीनन्दन ! दोषयुक्त होनेपर भी सहज कर्मका त्याग नहीं करना चाहिये; क्योंकि सम्पूर्ण कर्म धुएँसे अग्निकी तरह किसी-न-किसी दोषसे युक्त हैं।",
      "sa": "सहजं कर्म कौन्तेय सदोषमपि न त्यजेत्।सर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः।।18.48।।",
      "gu": "અર્જુનને કહેવામાં આવ્યું છે કે તે તેના સ્વભાવિક કર્મને છોડવું નહીં, ભલે તે તેમાં કાંઈક ખોટ હોય.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "हे कुन्तीनन्दन ! दोषयुक्त होनेपर भी सहज कर्मका त्याग नहीं करना चाहिये; क्योंकि सम्पूर्ण कर्म धुएँसे अग्निकी तरह किसी-न-किसी दोषसे युक्त हैं।",
    "englishTranslation": "One should not, O Arjuna, abandon the duty to which one is born, though it may be faulty; for, all undertakings are enveloped by evil, just as fire is by smoke."
