    "hindiMeaning": "हे कौन्तेय ! सिद्धि-(अन्तःकरणकी शुद्धि-) को प्राप्त हुआ साधक ब्रह्मको, जो कि ज्ञानकी परा निष्ठा है, जिस प्रकारसे प्राप्त होता है, उस प्रकारको तुम मुझसे संक्षेपमें ही समझो।",
    "englishTranslation": "Learn from Me, O Arjuna, in brief how one who has attained perfection reaches Brahman—the Eternal, that supreme state of knowledge."
