    "teluguMeaning": "భక్తితో, అతను నన్ను సత్యంలో తెలుసుకుంటాడు, నేను ఎవరు మరియు ఏమిటి; అప్పుడు, నన్ను సత్యంగా తెలుసుకున్న తరువాత, అతను వెంటనే పరమాత్మలో ప్రవేశిస్తాడు.",
    "iast": "bhaktyā mām abhijānāti yāvān yaśh chāsmi tattvataḥ\ntato māṁ tattvato jñātvā viśhate tad-anantaram",
    "translations": {
      "en": "By devotion, he knows Me in truth, who and what I am; then, having known Me in truth, he immediately enters into the Supreme.",
      "te": "భక్తితో, అతను నన్ను సత్యంలో తెలుసుకుంటాడు, నేను ఎవరు మరియు ఏమిటి; అప్పుడు, నన్ను సత్యంగా తెలుసుకున్న తరువాత, అతను వెంటనే పరమాత్మలో ప్రవేశిస్తాడు.",
      "hi": "उस पराभक्तिसे मेरेको, मैं जितना हूँ और जो हूँ -- इसको तत्त्वसे जान लेता है तथा मेरेको तत्त्वसे जानकर फिर तत्काल मेरेमें प्रविष्ट हो जाता है।",
      "sa": "भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम्।।18.55।।",
      "gu": "ભક્તિ દ્વારા વ્યક્તિ ભગવાનને તેમના વાસ્તવિક સ્વરૂપમાં ઓળખી શકે છે. આ શ્લોકમાં ભગવાન કૃષ્ણ સમજાવે છે કે ભક્તિ દ્વારા વ્યક્તિ તેમને તત્વથી જાણી શકે છે અને ત્યારબાદ તેઓના અસ્તિત્વમાં પ્રવેશ કરી શકે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "उस पराभक्तिसे मेरेको, मैं जितना हूँ और जो हूँ -- इसको तत्त्वसे जान लेता है तथा मेरेको तत्त्वसे जानकर फिर तत्काल मेरेमें प्रविष्ट हो जाता है।",
