      "en": "O Arjuna, bound by your own Karma (action) born of your own nature, that which from delusion you wish not to do, even that you shall do helplessly.",
      "te": "ఓ అర్జునా, నీ స్వభావము వలన పుట్టిన నీ స్వంత కర్మ (క్రియ)చే బంధింపబడి, భ్రాంతి నుండి నీవు చేయకూడదనుకున్నది, నిస్సహాయంగా చేస్తావు.",
      "hi": "हे कुन्तीनन्दन ! अपने स्वभावजन्य कर्मसे बँधा हुआ तू मोहके कारण जो नहीं करना चाहता, उसको तू (क्षात्र-प्रकृतिके) परवश होकर करेगा।",
      "sa": "स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।कर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत्।।18.60।।",
