      "te": "నా సర్వోన్నతమైన మాట, అన్నింటికంటే రహస్యం మళ్ళీ వినండి; మీరు నాకు చాలా ప్రియమైనవారు కాబట్టి, ఏది మంచిదో నేను మీకు చెప్తాను.",
