      "te": "సర్వ ధర్మాలను పరిత్యజించి, నన్ను ఒక్కడినే శరణు వేడుము. నేను నిన్ను సమస్త పాపాల నుండి విముక్తుడిని చేస్తాను, శోకించకుము.",
