      "en": "Arjuna said, \"My delusion has been destroyed, for I have gained my knowledge (memory) through Your grace, O Krishna. I am now free from doubts. I will act according to Your word.\"",
      "te": "అర్జునుడు \"ఓ కృష్ణా, నీ అనుగ్రహం ద్వారా నేను నా జ్ఞానాన్ని (జ్ఞాపకం) పొందాను కాబట్టి నా మాయ నశించింది. నేను ఇప్పుడు సందేహాల నుండి విముక్తి పొందాను. నీ మాట ప్రకారం నడుచుకుంటాను\" అన్నాడు.",
      "hi": "अर्जुन बोले -- हे अच्युत ! आपकी कृपासे मेरा मोह नष्ट हो गया है और स्मृति प्राप्त हो गयी है। मैं सन्देहरहित होकर स्थित हूँ। अब मैं आपकी आज्ञाका पालन करूँगा।",
      "sa": "अर्जुन उवाचनष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।स्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव।।18.73।।",
      "gu": "માં, અર્જુને પોતાની મોહભંગની સ્થિતિ વિશે વાત કરી છે. તે કહે છે કે કૃષ્ણની કૃપાથી તેના મોહનો નાશ થયો છે અને તે હવે સંશયમુક્ત છે.",
      "ta": null,
