      "te": "ఎక్కడ యోగేశ్వరుడైన శ్రీకృష్ణుడు, ఎక్కడ ధనుర్ధారియైన అర్జునుడు ఉంటారో, అక్కడ సంపద, విజయము, ఐశ్వర్యము, స్థిరమైన నీతి ఉంటాయని నా నిశ్చితాభిప్రాయము.",
      "hi": "जहाँ योगेश्वर भगवान् श्रीकृष्ण हैं और जहाँ गाण्डीवधनुषधारी अर्जुन हैं, वहाँ ही श्री, विजय, विभूति और अचल नीति है -- ऐसा मेरा मत है।",
      "sa": "यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः।\n\nतत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम।।18.78।",
      "gu": "ભગવાન શ્રી કૃષ્ણને 'યોગેશ્વર' તરીકે ઓળખાવવામાં આવે છે કારણ કે તેઓ યોગના મહાન સ્વામી છે. તેઓમાં યોગના આધ્યાત્મિક અને વ્યવહારિક પાસાઓનો સંપૂર્ણ સમન્વય છે. તેઓ જીવનના દરેક ક્ષેત્રમાં સંતુલન અને શાંતિ લાવી શકે છે.",
      "ta": null,
      "kn": null,
